m3_content = '''"""Tests for milestone m3: Support callable into in @reraise."""


def test_reraise_callable_into_transforms_exception():
    """Callable into receives the caught exception and returns the exception to raise."""
    from funcy import reraise

    @reraise(ValueError, lambda e: RuntimeError("wrapped: " + str(e)))
    def f():
        raise ValueError("bad")

    try:
        f()
        assert False, "Should have raised"
    except RuntimeError as e:
        assert "wrapped: bad" in str(e)


def test_reraise_static_form_preserves_exception_chain():
    """Existing static form @reraise(ValueError, TypeError) raises TypeError with chain."""
    from funcy import reraise

    @reraise(ValueError, TypeError)
    def f():
        raise ValueError("original error")

    try:
        f()
        assert False, "Should have raised"
    except TypeError as e:
        # Verify the original exception is preserved in the chain
        assert e.__cause__ is not None
        assert isinstance(e.__cause__, ValueError)
        assert str(e.__cause__) == "original error"


def test_reraise_callable_receives_exception_instance():
    """The callable into receives the caught exception instance."""
    from funcy import reraise

    captured = []

    def transformer(e):
        captured.append(e)
        return ValueError("transformed: " + str(e))

    @reraise(ValueError, transformer)
    def f():
        raise ValueError("original")

    try:
        f()
        assert False, "Should have raised"
    except ValueError as e:
        assert "transformed: original" in str(e)
    assert len(captured) == 1
    assert str(captured[0]) == "original"


def test_reraise_callable_returns_exception_instance():
    """Callable into can return an exception instance directly."""
    from funcy import reraise

    @reraise(ValueError, lambda e: ValueError("new message"))
    def f():
        raise ValueError("old message")

    try:
        f()
        assert False, "Should have raised"
    except ValueError as e:
        assert str(e) == "new message"
